(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["de"] = {"ui":{"lead":"Menschen haben Spiele nicht nur gespielt, sondern auch gemalt. Vergrößere 3300 Jahre Bilder und Figuren und entdecke die Details.","details":"Details","links":"Das Spiel ansehen oder spielen","record":"Zum Werk","game":"Spiel","exhibit":"Sammlung","room":"Saal","room_chance":"Zufall","hint":"Zum Zoomen ziehen oder scrollen · zum Verschieben ziehen · eine Nummer antippen","r_artist":"Künstler","r_date":"Datierung","r_place":"Ort","r_medium":"Technik","r_size":"Maße","r_museum":"Museum","r_credit":"Erwerb","r_rights":"Bild","met":"The Metropolitan Museum of Art","cc0":"Open Access (gemeinfrei)","metlink":"Das Werk auf der Website des Museums","credit":"Bilder: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago und das Rijksmuseum, Open Access (gemeinfrei).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Königin Nefertari beim Senet","artist":"Nina de Garis Davies (Faksimile)","date":"Original um 1290–1224 v. Chr. · Faksimile 1921–22","place":"Ägypten (Tal der Königinnen)","game":"Senet","medium":"Tempera auf Papier (Faksimile in halber Größe)","p":["Nefertari war die große königliche Gemahlin Ramses’ II. Dies ist die Kopie eines Gemäldes aus ihrem Grab im Tal der Königinnen, 1921–22 im Grab selbst angefertigt; sogar die Risse und Fehlstellen der Wand wurden mitkopiert.","Die Königin sitzt vor einem Brett und spielt Senet gegen einen unsichtbaren Gegner. In einem Grab gemalt, bedeutete das Spiel vermutlich mehr als Zeitvertreib: den Weg ins Jenseits zu gewinnen."],"spots":[["Zwei Arten von Steinen","Spitze Steine und spulenförmige Steine stehen auf dem Brett: je ein Satz für jeden Spieler."],["Die Hand der Königin","Ihre Finger greifen nach einem Stein."],["Brett und Gestell","Das Brett ist von der Seite gezeigt, darum sieht man die Felder nicht. Es ruht auf einem schmalbeinigen Gestell."],["Ihr Name","Der Name der Königin steht in einem Oval, einer Kartusche."],["Der unsichtbare Gegner","Niemand sitzt ihr gegenüber: Sie spielt gegen einen Gegner, den man nicht sieht."]]},"hydria":{"title":"Achill und Aias beim Brettspiel (Hydria)","artist":"Der Leagros-Gruppe zugeschrieben","date":"um 510 v. Chr.","place":"Griechenland (Attika)","game":"Ein Würfelspiel","medium":"Terrakotta (schwarzfigurig)","p":["Während der Belagerung Trojas vertreiben sich zwei griechische Helden, Achill und Aias, die Zeit an einem Brett. Erfunden hat die Szene um 540 v. Chr. der Töpfer und Maler Exekias; sein Original ist auf einer Amphora in den Vatikanischen Museen erhalten.","Das Thema war zwischen etwa 540 und 480 v. Chr. sehr beliebt; über 150 Beispiele sind bekannt. Auf dieser Hydria steht die Göttin Athena in der Mitte. Die Helden spielen ein Spiel, bei dem die Steine nach dem Wurf der Würfel ziehen."],"spots":[["Athena","Die Göttin Athena steht zwischen den beiden."],["Der Held links","Den Speer noch in der Hand, beugt er sich über das Brett."],["Der Held rechts","Auch er hat die Waffen nicht abgelegt: ein Augenblick Spiel mitten im Krieg."],["Das Brett","Der niedrige Block zwischen ihnen ist das Brett."],["Die Schulter","Auf der Schulter des Gefäßes fährt ein Wagen los."]]},"liubo":{"title":"Zwei sitzende Figuren beim Liubo","date":"1. Jh. v. Chr. – 1. Jh. n. Chr.","place":"China (Han-Dynastie)","game":"Liubo","medium":"Bemalte Irdenware","p":["Zwei Liubo-Spieler – Liubo war die große Mode im China der Han-Zeit. Solche Figuren gab man ins Grab mit dem Wunsch, dass die Freuden des Lebens nach dem Tod weitergehen.","Auf dem Foto liegen das Liubo-Brett und die Knochensteine aus der Sammlung dieses Museums zwischen ihnen. Die Figuren halten einen dramatischen Augenblick einer hitzigen Partie fest."],"spots":[["Das Liubo-Brett","Dasselbe Brett wie „Liubo-Brett mit Steinen“ in der Sammlung: Siehe die T-, L- und V-Zeichen."],["Der Spieler links","Er betrachtet das Brett in aller Ruhe."],["Der Spieler rechts","Die Hand erhoben, der Mund weit offen: Ist ihm gerade der entscheidende Zug gelungen?"],["Steine auf dem Brett","Knochensteine stehen an beiden Enden des Bretts."],["Steine neben dem Brett","Weitere Steine liegen auf dem Boden."]]},"shahnama":{"title":"„Buzurjmihr ergründet das indische Schachspiel“, aus dem Schahname des Schah Tahmasp","artist":"Malerei ʿAbd al-Vahhab zugeschrieben","date":"um 1530–35","place":"Iran (Täbris)","game":"Schach","medium":"Deckfarben, Tinte, Silber und Gold auf Papier","p":["Eine Szene aus Firdausis Epos, dem Schahname (Buch der Könige). Der König von Indien schickt einen Gesandten mit Schachbrett und Figuren und fordert den persischen König Nuschirwan heraus: Findet er heraus, wie das Spiel geht, zahlt Indien Tribut.","Nur der junge Weise Buzurjmihr löst das Rätsel rechtzeitig. Im Schahname schickt Persien zum Dank das Backgammon zurück, und die Inder können es nicht lösen. König und Höflinge starren auf das Brett und die Spieler."],"spots":[["Das Schachbrett","Die Figuren stehen auf einem karierten Brett, so klein, dass man ihre Formen kaum erkennt."],["König Nuschirwan","Auf seinem Thron wartet er auf die Lösung des Rätsels."],["Rund um das Brett","Die Spieler beugen sich über das Brett."],["Die Verse","Die Felder oben und unten tragen Verse Firdausis."],["Die Höflinge","Männer mit Turbanen mit hohen roten Stäben sehen stehend zu."]]},"chaupar":{"title":"Shiva und Parvati beim Chaupar, aus einer Rasamanjari-Serie","artist":"Devidasa von Nurpur","date":"1694–95","place":"Indien (Basohli, Jammu)","game":"Chaupar (verwandt mit dem Vorfahren von Ludo)","medium":"Deckfarben, Tinte, Silber und Gold auf Papier","p":["Ein Blatt aus einer Serie zur Rasamanjari, einem Sanskrit-Liebesgedicht des 15. Jahrhunderts. Der Gott Shiva und seine Gemahlin Parvati sitzen auf einem Tigerfell um ein kreuzförmiges Brett.","Shiva hat Parvati gerade mit einem Trick eine Halskette abgenommen, und sie fleht ihn an. Kühne Farben, eine unbestimmte Raumtiefe, Farbe und Geste mit Bedeutung: Das sind die Kennzeichen der Basohli-Schule."],"spots":[["Das kreuzförmige Brett","Chaupar und Pachisi spielt man auf einem Brett in dieser Kreuzform."],["Weiße Stäbe auf dem Brett","Wohl die langen Würfel (Pasa) des Chaupar."],["Shiva","Weiß am Körper, eine Schlange um den Hals."],["Parvati","Mit ausgestreckter Hand bittet sie um ihre Kette."],["Das Tigerfell","Beide sitzen auf einem Tigerfell."]]},"shogi":{"title":"Junge Frau und junger Mann beim Shōgi („Chūnagon Kanesuke“, aus den Sechsunddreißig Unsterblichen der Dichtkunst)","artist":"Suzuki Harunobu","date":"um 1767–69","place":"Japan (Edo)","game":"Shogi","medium":"Farbholzschnitt (Nishiki-e)","p":["Ein Blatt aus einer Serie, die auf die Sechsunddreißig Unsterblichen der Dichtkunst anspielt; dieses steht für den Dichter Chūnagon Kanesuke. In einer Sommernacht sitzen eine junge Frau und ein junger Mann neben einem Moskitonetz am Shogibrett.","Harunobu war der Künstler, der den vielfarbigen, mit vielen Druckstöcken gedruckten Holzschnitt populär machte. Selbst die Steine auf dem Brett sind genau gezeichnet."],"spots":[["Ein Shogibrett auf Füßen","Ein dickes Brett auf Füßen, wie man es heute noch hat."],["Ein Kästchen","Wohl das Kästchen für die Steine."],["Das Moskitonetz","Ein grünes Moskitonetz hängt im Raum: Es ist eine Sommernacht."],["Die Laterne","Eine Standlampe beleuchtet das Brett."],["Das Gedicht","Das wolkenförmige Feld trägt den Namen des Dichters und ein Gedicht."]]},"sugoroku":{"title":"Zwei junge Frauen beim Sugoroku","artist":"Utagawa Toyokuni I.","date":"Edo-Zeit (spätes 18. – frühes 19. Jh.)","place":"Japan (Edo)","game":"Ban-Sugoroku (verwandt mit Backgammon)","medium":"Diptychon aus Farbholzschnitten","p":["Zwei Holzschnitte, zu einem breiten Bild zusammengesetzt: Junge Frauen in einem Zimmer vergnügen sich beim Ban-Sugoroku. Das Spiel ist ein Verwandter des Backgammon, aus derselben Linie wie das Sugoroku-Brett aus dem Shōsōin in dieser Sammlung.","Weiße und schwarze Steine stehen auf dem Brett, und die junge Frau rechts hält einen Becher zum Würfeln. Durch das Fenster sieht man den Fuji."],"spots":[["Das Brett","Weiße und schwarze Steine auf seinen langen Feldern."],["Der Würfelbecher","In ihm werden die Würfel geschüttelt."],["Steine neben dem Brett","Schon hinausgespielt oder noch nicht eingesetzt?"],["Der Fuji","Der Fuji jenseits des Fensters."],["Die Nahtstelle","Hier treffen die beiden Holzschnitte aufeinander."]]},"eakins":{"title":"Die Schachspieler","artist":"Thomas Eakins","date":"1876","place":"USA (Philadelphia)","game":"Schach","medium":"Öl auf Holz","p":["Im Salon eines Hauses in Philadelphia spielen zwei Freunde Schach, während der Vater des Künstlers, Benjamin Eakins, zusieht. Seinen sorgfältigen Raumaufbau und die genauen Details hatte Eakins bei seinem Pariser Lehrer Gérôme gelernt.","1881 wurde Die Schachspieler das erste Werk, das das Metropolitan Museum als Schenkung eines lebenden Künstlers annahm."],"spots":[["Die Schachfiguren","Im dämmrigen Raum leuchten die Figuren auf dem Brett im Licht auf."],["Der Vater des Künstlers","Stehend verfolgt er die Partie: Benjamin Eakins."],["Der Spieler rechts","Der Maler George W. Holmes, ein Freund des Vaters."],["Die Schublade","Eine lateinische Inschrift: „Benjamin Eakins’ Sohn malte dies im Jahr ’76.“"],["Über dem Kamin","Eine Reproduktion eines Gemäldes von Gérôme, Eakins’ Lehrer."],["Die Katze","Auf dem Boden scheint nur die Katze sich nicht für die Partie zu interessieren."]]},"weiqi":{"title":"Schale mit Unsterblichen beim Weiqi","artist":"Unbekannt","date":"1425–36 (Ming-Dynastie, Xuande-Ära)","place":"China","game":"Go (Weiqi)","medium":"Geschnitzter roter und grüner Lack","size":"H. 3,5; B. 14,9; L. 23,5 cm","credit":"Geschenk von Florence und Herbert Irving, 2015","p":["Eine Schale aus Schnitzlack: Dutzende Lackschichten wurden aufgetragen und dann geschnitzt; unter dem Rot liegt eine grüne Schicht, sodass die Schnitttiefe die Farben hervorholt. Im gelappten Rand spielen Unsterbliche unter einer Kiefer Go.","In China gibt es die Legende von Lanke, dem „verfaulten Axtstiel“: Der Holzfäller Wang Zhi sah in den Bergen Unsterblichen beim Go zu und merkte erst danach, dass so viel Zeit vergangen war, dass sein Axtstiel verfault war. Unsterbliche am Brett waren ein beliebtes Motiv. Wer die stehende Figur ist, sagen die Quellen nicht."],"spots":[["Das Brett","Das Go-Brett zwischen den beiden Unsterblichen, bis in die Linien geschnitzt."],["Die spielenden Unsterblichen","Zwei Gestalten sitzen bei den Felsen um das Brett."],["Die stehende Figur","Eine Figur steht etwas abseits. Sie erinnert an den Holzfäller der Legende, doch wer sie ist, ist unbekannt."],["Der Mond","Ein runder Mond am Himmel (oder vielleicht die Sonne)."],["Die Kiefer","Eine ausladende Kiefer, ein Baum, der oft für langes Leben und das Land der Unsterblichen steht."],["Der Päonienrand","Große Päonien und Blätter sind rund um den Rand geschnitzt."]]},"webb":{"title":"Die Backgammonspieler (Schrank)","artist":"Philip Webb (Entwurf), Edward Burne-Jones (Malerei), Morris, Marshall, Faulkner & Co. (Herstellung)","date":"1861","place":"Großbritannien (London)","game":"Backgammon","medium":"Bemaltes Kiefernholz, Öl auf Leder, Messing, Kupfer","size":"H. 185,4; B. 114,3; T. 53,3 cm","credit":"Rogers Fund, 1926","p":["Eines der frühesten Möbel der Firma, die William Morris 1861 mit Freunden gründete. Auf dem Leder der Türen sitzen ein Mann und eine Frau in mittelalterlicher Kleidung beim Backgammon, in Öl gemalt. Der Schrank wurde 1862 auf der Internationalen Ausstellung in London gezeigt.","Er fasst das Ziel der Arts-and-Crafts-Bewegung zusammen, die Grenze zwischen bildender und angewandter Kunst aufzuheben. Der Lederhintergrund ist mit winzigen Punkten gepunzt, einer mittelalterlichen Technik."],"spots":[["Das Brett","Das Backgammonbrett auf dem Tisch zwischen den beiden."],["Der Mann","Ein junger Mann, einen Stein in der Hand, betrachtet das Brett."],["Die Frau","Ihm gegenüber hält eine Frau einen Stein (oder einen Würfelbecher)."],["Blumen zu ihren Füßen","Zu Füßen der Spieler blühen Blumen."],["Gepunztes Leder","Der Lederhintergrund ist mit feinen Punkten gepunzt, die das Licht fangen."],["Rautenbänder","Rautenbänder auf Gold rahmen die Türen oben und unten."]]},"liberale":{"title":"Die Schachspieler","artist":"Liberale da Verona","date":"um 1475","place":"Italien (Verona)","game":"Schach","medium":"Tempera auf Holz","size":"34,9 × 41,3 cm","credit":"Sammlung Maitland F. Griggs, Vermächtnis von Maitland F. Griggs, 1943","p":["Ein Fragment von der Front eines Cassone, der bemalten Truhe, in der eine Braut im Italien der Renaissance ihre Aussteuer aufbewahrte. Liberale war auch für seine Buchmalereien in den Chorbüchern des Doms von Siena bekannt.","Es zeigt einen Augenblick aus einer nicht bestimmten Liebesgeschichte. Auf dem Gegenstück scheint ein Mädchen am Fenster einen jungen Mann hereinzuwinken; hier spielen die beiden Schach. Laut Museum steht sie kurz davor zu verlieren. Schach war in der Liebesdichtung der Zeit ein beliebtes Bild für das Werben."],"spots":[["Das Schachbrett","Ein rot-weißes Brett mit dunklen Figuren; die Partie scheint dem Ende nahe."],["Der junge Mann","Er greift zum Brett und steht wohl vor dem Sieg."],["Das Mädchen","Ihm gegenüber; auf dem Gegenstück winkt sie ihn vom Fenster aus herein."],["Das Fenster","Hinter dem offenen Fenster ein Hügel und der Himmel."],["Zuschauende junge Männer","Männer mit verschränkten Armen verfolgen die Partie."],["Zuschauende junge Frauen","Frauen schauen hinter der Säule dem Spiel zu."]]},"mirror":{"title":"Spiegelkapsel mit Schach spielendem Paar","artist":"Unbekannt","date":"1325–50","place":"Frankreich (Paris)","game":"Schach","medium":"Elfenbein","size":"Durchmesser 10,2 cm","credit":"Erworben aus dem J. H. Wade Fund, 1940","p":["Diese handtellergroße Elfenbeinscheibe war der Deckel eines Handspiegels. Im Paris des 14. Jahrhunderts steckte ein polierter Metallspiegel zwischen zwei Elfenbeinplatten und wurde bei sich getragen; solche Schnitzereien waren Luxusgüter, die Hof und Adel schätzten.","In einem Zelt mit gerafften Vorhängen spielen ein junger Mann und eine Dame Schach. In den Romanen des Mittelalters stand Schach zugleich für Liebe und Krieg. Man hat in dem Paar Tristan und Isolde oder Lancelot und Guinevere sehen wollen, doch niemand weiß es. Das Museum fragt seine Besucher: Wer gewinnt wohl gerade?"],"spots":[["Das Schachbrett","Ein Brett auf einem einbeinigen Tisch, auf dem einige Figuren stehen."],["Der junge Mann","Er greift hinüber, um seinen nächsten Zug zu machen."],["Die Dame","Eine Frau mit Haube; ihre Fingerspitzen berühren eine Figur."],["Die geschlossene Hand","Ihre andere Hand liegt geschlossen im Schoß. Hält sie eine geschlagene Figur?"],["Das Zelt","Beidseitig geraffte Vorhänge – eine beliebte Kulisse für Schachszenen auf Spiegelkapseln."]]},"morris":{"title":"Ein Spielbrett (Mühle)","artist":"Peter Flötner","date":"1500–46","place":"Deutschland","game":"Mühle","medium":"Holzschnitt","credit":"Charles W. Harkness Endowment Fund, 1923","p":["Ein Holzschnitt von Peter Flötner, einem der begabtesten Bildhauer im Nürnberg der Renaissance, der auch Ornamente, Möbel, Goldschmiedemodelle und ein für seine Satire berühmtes Kartenspiel entwarf. Unter dem wirbelnden Rankenwerk verbirgt sich das Brett der Mühle: drei ineinanderliegende Quadrate, die in der Mitte jeder Seite verbunden sind.","Das Brett hat 24 Punkte. Wer drei eigene Steine in eine Reihe bringt (eine Mühle), nimmt dem Gegner einen weg. Solche Drucke dienten Handwerkern auch als Vorlagen; das Museum zeigte dieses Blatt in einer Ausstellung von Goldschmiedemodellen und -entwürfen. Ob man auf dem Papier selbst spielte oder es in Holz oder Metall übertrug, ist nicht überliefert."],"spots":[["Das mittlere Quadrat","Das innerste Quadrat, ganz mit feinem Flechtwerk gefüllt."],["Eine äußere Ecke","Eine Ecke des äußeren Quadrats – einer der 24 Punkte für die Steine."],["Eine mittlere Ecke","Auch die Ecken des mittleren Quadrats sind Punkte."],["Die Verbindungslinien","Bänder verbinden die drei Quadrate in der Mitte jeder Seite; auch auf ihnen ziehen die Steine."],["Eine Maske","Rollwerkkartuschen mit Gesichtern oben, unten und an den Seiten – Groteskenornament der Renaissance."],["Die Weinrankenbordüre","Blätter und Früchte, weiß aus dem schwarzen Grund geschnitten."]]},"leifeng":{"title":"Brettspiel der Leifeng-Pagode","artist":"Unbekannt","date":"1736–95 (Qianlong-Zeit)","place":"China","game":"Wettlaufspiel","medium":"Holzschnitt; Tusche auf Papier","size":"31 × 29,8 cm","credit":"Erworben aus dem J. H. Wade Fund, 2025","p":["Ein zum Spielen gedrucktes Einzelblatt aus der Regierungszeit des Qianlong-Kaisers im China der Qing. Auf seinen Feldern stehen die Figuren der Legende von der Weißen Schlange: der Schlangengeist Bai Suzhen („Weiße Dame“), ihre Gefährtin Xiaoqing („Kleine Grüne“), der junge Xu Xuan (in späteren Fassungen Xu Xian) und der Mönch Fahai, der die Weiße Dame am Ende unter der Leifeng-Pagode am Westsee einschließt.","Die Bahn windet sich von einem Feld mit der Aufschrift 起馬, „los“, spiralförmig zur Pagode in der Mitte. Vermutlich lief man mit Würfeln durch die Geschichte, ähnlich wie beim abendländischen Gänsespiel; die Regeln sind nicht überliefert. Laut Museum wurden solche Farbdrucke in den Städten verkauft und an die Wand gehängt – Teil der städtischen Bildkultur, jede Farbe von einem eigenen geschnittenen Stock gedruckt."],"spots":[["Start","Das Feld mit 起馬, „los“ – vermutlich der Startpunkt."],["Weiße Dame und Kleine Grüne","Der Schlangengeist Bai Suzhen und ihre Gefährtin Xiaoqing."],["Xu Xuan","Der junge Mann, der die Weiße Dame heiratet."],["Der Mönch Fahai","Der Mönch, der sie unter der Pagode einschließt."],["Die Leifeng-Pagode","Die Pagode am Westsee in Hangzhou, wo die Geschichte endet."],["Die Mitte","Eine Frau vor der Pagode und ein kniender Mann – die letzte Szene der Geschichte und vielleicht das Ziel."]]},"tutinama":{"title":"Der verwundete Affe beißt dem Prinzen, seinem Schachpartner, in die Hand (aus einem Tuti-nama, Erzählungen eines Papageis)","artist":"Dasavanta","date":"um 1560","place":"Indien (Mogulhof Akbars)","game":"Schach","medium":"Gouache, Tusche und Gold auf Papier","size":"20 × 14,2 cm (Bild 10,2 × 10,6 cm)","credit":"Schenkung von Mrs. A. Dean Perry, 1962","p":["Eine Illustration aus dem Tuti-nama, den „Erzählungen eines Papageis“, entstanden am Hof des Mogulkaisers Akbar. Es ist eine der Geschichten, mit denen eine Papageienmutter ihre Jungen vor Freundschaften mit anderen Tierarten warnt – etwa mit den Fuchswelpen. Darin spielte ein schachkundiger Affe oft mit einem Prinzen.","Eines Tages machte der Affe vor Gästen einen bösen Scherz; der Prinz ohrfeigte ihn, und der Affe biss ihm in die Hand. Rechts draußen bereiten Diener das Essen, während die Gäste verblüfft zusehen. Eine Inschrift unten nennt Dasavanta, der später zu den berühmtesten Meistern am Mogulhof gehörte; als junger Maler legte er eine kühle blaue Schicht unter sein Bild."],"spots":[["Der Affe","Er beißt dem Prinzen, seinem Schachpartner, in die Hand."],["Der Prinz","Der gebissene Prinz."],["Das Schachbrett","Ein Brett mit roten Feldern auf dem Boden."],["Die verblüfften Gäste","Die geladenen Gäste."],["Das Essen","Draußen setzen Diener Töpfe aufs Feuer."],["Der persische Text","Oben steht die Geschichte auf Persisch."]]},"teniers":{"title":"Die Backgammonpartie","artist":"David Teniers","date":"1640er Jahre","place":"Flandern","game":"Backgammon","medium":"Öl auf Holz, auf Leinwand übertragen","size":"59 × 80,6 cm","credit":"Schenkung von Mr. und Mrs. Samuel D. Wise, 1943","p":["Eine Backgammonpartie um hohe Einsätze, gemalt vom Flamen Teniers. Das Spiel ist sehr alt: Seine heutige Form entstand im 15. Jahrhundert, und der Name „Backgammon“ kam etwa zur Zeit dieses Bildes auf. Im 17. Jahrhundert war es äußerst beliebt und wurde oft um Geld gespielt.","Zuschauer drängen sich um die beiden Spieler, und an der Wand führt jemand Buch. Wegen der zuschauenden Frauen – eine lehnt aus einem Fenster – hält das Museum den Raum für das Spielzimmer eines Bordells. Solche Spielszenen trugen oft eine Moral: Glücksspiel sei töricht, ja verwerflich, und Zeitverschwendung."],"spots":[["Das Brett","Ein aufgeklapptes Backgammonbrett auf dem Tisch, die Partie läuft."],["Der Mann in Weiß","Ein Spieler von hinten, der nach seinen Steinen greift."],["Der Grübler","Sein Gegner, die Wange in die Hand gestützt."],["Der Anschreiber","Ein Mann markiert eine Tafel an der Wand – Punkte oder Einsätze?"],["Die Frau am Fenster","Eine ältere Frau schaut von oben zu."],["Das Hinterzimmer","Hinten trinken Männer neben einer jungen Frau."]]},"imari":{"title":"Schale mit zwei Go-Spielern","artist":"Unbekannt","date":"18. Jahrhundert","place":"Japan (Edo-Zeit)","game":"Go","medium":"Porzellan, geformt, mit Aufglasurfarben (Hizen, Imari-Stil)","size":"2,4 × 13,8 cm","credit":"Severance and Greta Millikin Collection, 1964","p":["Auf dieser kleinen quadratischen Schale spielen zwei Männer unter einer Kiefer Go: der eine in Gelb sitzt vor dem Brett, das direkt auf dem Boden liegt; sein Gegner in Grün lehnt am Baum.","Es ist Imari-Porzellan aus Hizen (heute Saga und Nagasaki); seine Grüntöne erinnern an Kutani-Emails. Gefertigt wurde es für den Export, als Japan China als wichtigsten Porzellanlieferanten Europas abgelöst hatte."],"spots":[["Das Go-Brett","Ein gerastertes Brett, direkt auf dem Boden."],["Der Mann in Gelb","Er sitzt vor dem Brett."],["Der Mann in Grün","Sein Gegner, lächelnd an den Baum gelehnt."],["Die Kiefer","Eine Kiefer breitet ihre Zweige über ihnen aus."],["Der rote Rahmen","Ein roter Rahmen mit abgeschrägten Ecken umgibt die Szene."]]},"shoei":{"title":"Die vier Künste (einer von zwei Stellschirmen)","artist":"Kanō Shōei zugeschrieben","date":"spätes 16.–frühes 17. Jahrhundert","place":"Japan (Momoyama-Zeit)","game":"Go","medium":"Einer von zwei sechsteiligen Stellschirmen; Tusche und leichte Farben auf Papier","size":"153 × 358,6 cm","credit":"John L. Severance Fund, 1979","p":["Ein sechsteiliger Stellschirm, Kanō Shōei aus der Kanō-Schule zugeschrieben. Zusammen mit seinem Gegenstück zeigt er die „vier Künste“, die man von einem gebildeten chinesischen Herrn erwartete: Qin spielen, Qi (Go) spielen, Kalligrafie und Malerei. Hier ruhen vornehme chinesische Herren mit ihren Dienern unter Kiefern auf dem Land.","In der Mitte spielen zwei Männer Go, ein dritter schaut zu. Daneben stehen auf einem Tisch Bücher und eine Qin, noch in ihrer Stoffhülle, die darauf wartet, gespielt zu werden. Die Szene hält Vergnügen und Förmlichkeit im Gleichgewicht. Das Museum weist darauf hin, dass einer der Diener von einem Fisch im Wasser abgelenkt ist."],"spots":[["Das Go-Brett","Ein Brett mit Füßen; zwei Herren spielen einander gegenüber."],["Die Herren","Zwei Spieler und ein dritter, der zuschaut."],["Der Tisch","Wohl der Tisch mit den Büchern und der Qin in ihrer Hülle."],["Die Diener","Diener, die beim Tisch warten."],["Der abgelenkte Diener","Am Wasser liegend, schaut er einem Fisch zu."],["Die Kiefer","Eine große Kiefer breitet ihre Zweige über die Szene."]]},"umaya":{"title":"Stallschirm (Go und Shogi auf der Veranda)","artist":"Unbekannt","date":"Frühes 16. Jahrhundert","place":"Japan (Muromachi-Zeit)","game":"Go und Shogi","medium":"Einer von zwei sechsteiligen Stellschirmen; Tusche, Farben und Gold auf Papier","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Dieser Stellschirm aus sechs verbundenen Feldern ist einer von einem Paar. Die wertvollen Pferde in ihren Ständen mögen das Hauptthema sein, doch auf der Veranda davor ist viel los.","Dort fordern sich Menschen in zwei Brettspielen heraus: links Go, rechts Shogi. Wie das Museum schreibt, lebt die Szene vom Wechselspiel zwischen den unruhigen Pferden und der stillen Strategie der Spiele. In Japan galten Affen als Beschützer der Pferde und wurden manchmal in Ställen gehalten."],"spots":[["Das Go-Brett","Ein fein liniertes Brett mit schwarzen Steinen."],["Zwei Männer mit schwarzer Kappe","Männer mit hoher schwarzer Eboshi-Kappe: der in Grün greift zum Brett, der in Rot schaut zu."],["Das Shogi-Brett","Große Felder – viel weniger als auf dem Go-Brett."],["Der lachende Gegner","Ein kahlgeschorener Mönch nimmt einen Stein, während der Mann gegenüber sich an den Kopf fasst und laut lacht. Hat gerade jemand gepunktet?"],["Ein Affe","Am Ende der Veranda – ein Affe in rotem Rock?"],["Ein Pferd","Ein schwarzes Pferd bäumt sich auf, von Seilen gehalten."]]},"goryeo":{"title":"Kanne mit eingelegten Go-Spielern","artist":"Unbekannt","date":"13. Jahrhundert","place":"Korea (Goryeo-Dynastie)","game":"Go (Baduk)","medium":"Seladon mit Einlagen aus weißem und schwarzem Schlicker","size":"H. 20,4 cm, Dm. 14,3 cm","credit":"Geschenk von John L. Severance, 1917","p":["Eine Seladonkanne der Goryeo-Zeit mit Tülle und Henkel. Die Einlagetechnik – Linien in den Ton ritzen, mit weißem und schwarzem Schlicker füllen, dann glasieren und brennen – war die Spezialität der Goryeo-Töpfer; hier heben sich in einem runden Medaillon zwei unter einer Weide sitzende Gestalten weiß ab.","Zwischen ihnen liegt ein Brett, und das Museum vergleicht die Szene mit Bildern vom Go-Spiel – auf Koreanisch Baduk. Zither, Go, Kalligrafie und Malerei waren die „vier Künste“ des gebildeten Gelehrten, und ihre eleganten Zusammenkünfte wurden auch zu Motiven des Kunsthandwerks. Koreanisches Seladon mit Menschenfiguren ist selten."],"spots":[["Das Brett","Das Brett zwischen den beiden, ein weißes Quadrat."],["Die Gestalt links","Sitzt dem Brett zugewandt."],["Die Gestalt rechts","Der Gegner, gegenüber sitzend."],["Die Weide","Weidenzweige hängen über ihnen, mit schwarzem Schlicker gezeichnet."],["Der Wolkenrahmen","Wolkenartige Ranken umlaufen das runde Medaillon."],["Das Craquelé","Feine Risse in der Glasur. Sie entstehen beim Abkühlen, weil Ton und Glasur verschieden stark schwinden."]]},"kangra":{"title":"Paar beim Chaupar auf einer Terrasse","artist":"Unbekannt","date":"um 1790–1800","place":"Indien (Pahari, Kangra-Schule)","game":"Chaupar","medium":"Zeichnung mit Vorzeichnung in rotem Ocker","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Eine Zeichnung eines Künstlers aus Kangra in den Pahari-Bergen am Fuß des Himalaya. Die erste Skizze entstand in Rot (roter Ocker) und wurde dann in Schwarz ausgearbeitet. Da keine Farbe darüberliegt, lässt sich jede Linie der Figuren und Gegenstände verfolgen.","Ein Mann und eine Frau sitzen auf einer Terrasse zu beiden Seiten eines kreuzförmigen Bretts und spielen Chaupar – ein altes indisches Laufspiel auf demselben Kreuz wie Pachisi, bei dem man mit langen Würfeln (Pasa) zieht. Die Felder sind auf dem Brett noch nicht eingezeichnet. Dienerinnen umsorgen das Paar."],"spots":[["Das Kreuzbrett","Ein kreuzförmiges Brett auf dem Boden. Seine Felder sind noch nicht gezeichnet."],["Die Frau","Die Handfläche nach oben – gleich wirft sie die Würfel?"],["Der Mann","Turban mit Federbusch; er greift zum Brett."],["Die Dienerin links","Sie hält ein Fläschchen und reicht ein Tuch."],["Die Dienerin rechts","Sie hält ein langstieliges Gerät und ein kleines Gefäß."],["Die rote Vorzeichnung","Rund um den Turban schimmert die rote Skizze unter den schwarzen Linien hervor."]]},"vuillard":{"title":"Die Damepartie (aus Landschaften und Interieurs)","artist":"Édouard Vuillard","date":"1899","place":"Frankreich","game":"Dame","medium":"Farblithografie (Zustand III/III); gedruckt von Auguste Clot, verlegt von Ambroise Vollard","size":"Bild 33 × 25,7 cm (Blatt 38 × 30,8 cm)","credit":"Geschenk des Hanna Fund, 1951","p":["Ambroise Vollard, Händler impressionistischer Malerei, war auch ein bedeutender Verleger von Druckgrafik. 1895 gab er bei Pierre Bonnard eine Mappe mit 12 Farblithografien in Auftrag; viele weitere folgten, darunter Vuillards Landschaften und Interieurs, gedruckt vom Meisterdrucker Auguste Clot.","Bonnard und Vuillard gehörten zu den Nabis – hebräisch für „Propheten“ –, die eine neue Kunst suchten, in der Form und Farbe selbst Gefühl ausdrücken, und die Szenen aus dem Stadt- und Familienleben liebten. In einem Raum voller Muster sitzen sich zwei Männer am Damebrett gegenüber, eine Frau steht daneben und schaut zu. Auf Französisch heißt das Spiel „dames“; die Bleistiftnotiz unten links lautet „partie de dames“, eine Damepartie."],"spots":[["Das Brett","Ein kleines kariertes Brett mit den aufgestellten Steinen."],["Der Mann links","Ein bärtiger Mann greift über das Brett."],["Der Mann rechts","Sein Gegner, im Sessel über das Brett gebeugt, halb verdeckt von der stehenden Frau."],["Die stehende Frau","Die Hand am Kinn, verfolgt sie die Partie."],["Die Lampe","Eine Lampe an der Wand. Tapete und Polster sind voller Muster."],["Die Bleistiftnotiz","Unten links mit Bleistift: „partie de dames“ – eine Damepartie."]]},"talbot":{"title":"Die Schachspieler (frühe Fotografie)","artist":"William Henry Fox Talbot zugeschrieben","date":"um 1843–47","place":"England","game":"Schach","medium":"Salzpapierabzug","size":"19,9 × 15 cm","credit":"Erworben mit Mitteln von Mr. und Mrs. Everett Kovler","p":["Talbots Negativ-Positiv-Verfahren und die beliebig vielen Abzüge, die es ermöglichte, prägten die Fotografie bis ins digitale Zeitalter. Seine frühen Versuche zeigen wissenschaftliches Interesse wie künstlerischen Anspruch; nachweislich machte er zehn oder mehr Aufnahmen von Schachspielern.","Diese aber stammt vielleicht nicht von ihm: Dieser und andere Abzüge der Szene sind unsigniert und auf anderem Papier als Talbots üblichem. Die Dargestellten sind wohl der Fotograf Antoine Claudet und Talbots Assistent Nicolaas Henneman; neuere Forschung vermutet, dass die Bilder in Claudets Atelier entstanden, an Henneman gingen und zu Talbot kamen, als Henneman ihm Abzüge zur Begleichung einer Schuld gab (Museumstext)."],"spots":[["Das Brett","Das Schachbrett auf dem Tisch, die Figuren aufgereiht."],["Der Mann mit Zylinder","Den Hut noch auf, greift er nach einer Figur."],["Der Grübler","Die Hand am Kinn, studiert der Gegner das Brett."],["Der Vorhang","Ein Vorhang im Hintergrund – eine Kulisse für die Aufnahme?"],["Ein zweiter Hut","Ein weiterer Zylinder liegt rechts auf dem Gestell."]]},"pvl":{"title":"Würfelspielende Männer","artist":"Meister PVL","date":"um 1520","place":"Niederlande","game":"Würfel","medium":"Kupferstich auf Papier","size":"9,4 × 9,4 cm (rund)","credit":"Charles Hack und Hearn Family Trust Collection, erworben 2023","p":["Das Werk eines namentlich unbekannten Stechers, der zu Beginn des 16. Jahrhunderts in den Niederlanden tätig war; nach dem Monogramm „PVL“ unten links heißt er Meister PVL. Auf einem runden Blatt, das in eine Handfläche passt, bauen dichte, feine Linien die Tiefe des Raums und die Stofflichkeit der Kleider auf.","Auf dem Tisch liegen zwei Würfel. Ein vorgebeugter Mann und ein Jüngling mit Pelzkragen zeigen mit dem Finger und streiten – vielleicht um die Augenzahl. Hinten schauen Frauen zu, unter dem Tisch steht ein Weinkrug. Würfel sind seit der Antike mit dem Glücksspiel verbunden und wurden immer wieder verboten."],"spots":[["Die Würfel","Zwei Würfel rollen über den Tisch."],["Zeigende Hände","Zwei Finger treffen sich auf dem Tisch – Streit um die Augenzahl?"],["Der Mann mit breitem Hut","Vorgebeugt; seine geschlitzten Puffärmel waren damals Mode."],["Der Jüngling mit Pelzkragen","Großer Hut und Pelzkragen."],["Die zuschauenden Frauen","Frauen spähen von hinten auf das Spiel."],["Das Monogramm","„PVL“ unten links – der einzige Hinweis auf den Namen des Künstlers."]]},"kiyohiro":{"title":"Sugoroku-Spielerinnen","artist":"Torii Kiyohiro","date":"um 1750","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Farbholzschnitt (Benizuri-e), Ōban; Verleger Urokogataya","size":"43,5 × 29,3 cm","credit":"Clarence Buckingham Collection","p":["Torii Kiyohiro war ein Ukiyo-e-Künstler, tätig etwa von 1737 bis 1776. Dies ist ein Benizuri-e, gedruckt mit wenigen Farbplatten – Beni-Rosa, Grün und Ähnlichem – in den Jahren, bevor 1765 die vielfarbigen Nishiki-e aufkamen.","Auf dem schwarzen Gestell wird Ban-Sugoroku gespielt: Zwei Spieler würfeln und ziehen weiße und schwarze Steine; wer zuerst alle eigenen hinausgespielt hat, gewinnt. Es gehört zur selben Familie wie Backgammon, und Ukiyo-e-Drucke zeigen oft Frauen bei diesem Spiel. Dahinter raucht eine Frau eine lange Pfeife und sieht zu."],"spots":[["Das Brett","Ein Sugoroku-Brett auf seinem Gestell, mit weißen und schwarzen Steinen."],["Die Gestalt links","Sie greift nach einem Stein."],["Die Frau rechts","Über das Brett gebeugt, studiert die Gegnerin die Steine."],["Die Frau mit der Pfeife","Mit langer Kiseru-Pfeife verfolgt sie das Spiel von hinten."],["Die erhobene Hand","Die Frau rechts hält etwas Kleines, Schwarzes hoch – den Würfelbecher?"],["Die Signatur","„Torii Kiyohiro hitsu“, mit dem Siegel des Verlegers Urokogataya."]]},"ingram":{"title":"Das chinesische Schachspiel","artist":"John Ingram, nach François Boucher","date":"1741–63","place":"Frankreich (Paris)","game":"Xiangqi","medium":"Radierung und Kupferstich","size":"Blatt 39,4 × 27,7 cm (Platte 24,5 × 16,4 cm)","credit":"Elisha Whittelsey Collection, 1966","p":["Eine Zeichnung des französischen Malers François Boucher, gestochen vom gebürtigen Londoner John Ingram. Ingram zog nach Paris und schuf zwischen 1741 und 1763 eine Folge von Stichen nach Bouchers Chinoiserien – China, wie Europäer es sich vorstellten. Der Titel lautet „LE JEU D'ECHETS CHINOIS“, das chinesische Schachspiel.","Eine Frau mit hochgestecktem Haar zieht eine Figur auf dem Brett auf ihrem Schoß, ein kleines Kind schaut zu. Das Spiel gilt als Xiangqi, doch echte Xiangqi-Steine sind alle flache Scheiben, während hier hohe Figuren neben kleinen viereckigen stehen. Auch die Palme und die Figur auf der Urne gehören weniger zu China als zu dem fernen Land, von dem Europa damals träumte."],"spots":[["Brett und Figuren","Das Brett auf ihrem Schoß, mit hohen und viereckigen Figuren. Echte Xiangqi-Steine sind flache Scheiben."],["Die Hand an der Figur","Ihre rechte Hand zieht eine Figur."],["Kinn in der Hand","Die linke Hand am Kinn, blickt sie auf das Brett."],["Das zuschauende Kind","Ein Kind steht am Brett und verfolgt das Spiel."],["Die Figur auf der Urne","Eine Figur sitzt mit gekreuzten Beinen auf einer großen Urne."],["Titel und Namen","„Dessiné par Fr. Boucher“, „Gravé par Ingram“ und der Titel „LE JEU D'ECHETS CHINOIS“."]]},"posada":{"title":"Das Gänsespiel","artist":"José Guadalupe Posada","date":"1909","place":"Mexiko","game":"Gänsespiel","medium":"Hochdruck von Zinkplatte auf Papier","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Ein Spielbogen des mexikanischen Grafikers Posada – berühmt für seine Skelett-Calaveras – für den Verleger Antonio Vanegas Arroyo in Mexiko-Stadt. Das Band unten links lautet „JUEGO DE LA OCA“ (Gänsespiel), und die Bahn windet sich von Feld 1 bis zur 63 in der Mitte.","In der Mitte stehen die Regeln (EXPLICACION): Ein erster Wurf von 5 und 4 führt auf 26, von 6 und 3 auf 53. Wer auf eine Gans (einen Vogel) kommt, zieht dieselbe Zahl noch einmal; im Wirtshaus (Venta, 19) setzt man zwei Würfe aus; im Brunnen (Poso, 31) und im Gefängnis (Carcel, 52) bleibt man, bis ein anderer kommt; das Labyrinth (42) schickt zurück auf 39, der Tod (Muerte, 58) an den Start. Die 63 muss genau getroffen werden. Auf bestimmten Feldern zahlte man Einsätze – es war auch ein Glücksspiel."],"spots":[["Die Regeln","Die „EXPLICACION“ in der Mitte: was jedes Feld bewirkt und wann ein Einsatz fällig ist."],["Feld 1","Der Start. Von hier windet sich die Bahn zur Mitte."],["Der Brunnen (31)","Ein Brunnen wie eine Fontäne. Wer hineinfällt, bleibt, bis ein anderer kommt."],["Der Tod (58)","Das Totenkopffeld: zurück an den Start."],["Das Titelband","„JUEGO DE LA OCA“ auf dem Band unten links, darunter spielende Kinder."],["Der Name des Verlegers","Das Band der Göttin trägt „IMPRENTA DE A. VANEGAS ARROYO“ – der Verlag vieler Drucke Posadas."]]},"jintile":{"title":"Fliese mit Frauen beim Brettspiel","artist":"Unbekannt","date":"13. Jahrhundert","place":"China (Jin-Dynastie)","game":"Brettspiel (wohl Go)","medium":"Irdenware (geformtes Relief)","size":"H. 27,3 cm, B. 24,8 cm, T. 5,4 cm","credit":"Erworben mit Spenden der Friends of Asian Art, 2002","p":["Eine Relieffliese aus der Zeit der Jin (1115–1234), der Dynastie der Dschurdschen, die Nordchina beherrschten. Unter einem blühenden Baum sitzen sich zwei Frauen auf einem Podest gegenüber, ein Brett zwischen sich.","Das Brett zeigt ein feines Gitter – sie spielen wohl Go. Die rechte Frau beugt sich vor und zeigt auf das Brett, die linke schaut zu. Viele Gräber der Jin-Zeit in Nordchina waren mit Reliefziegeln voller Alltagsszenen ausgekleidet, und diese Fliese schmückte vermutlich ein solches Grab."],"spots":[["Das Brett","Ein fein gerastertes Brett, wohl ein Go-Brett."],["Die zeigende Hand","Die rechte Frau zeigt auf das Brett. Ihr nächster Zug?"],["Die Frau links","Mit hochgestecktem Haar blickt sie auf das Brett."],["Die Frau rechts","Über das Brett gebeugt."],["Der blühende Baum","Über ihnen breiten sich die Zweige eines blühenden Baums aus."],["Das Podest","Das Podest, auf dem sie sitzen, mit einer gewellten Zarge zwischen den Beinen."]]},"kyosai":{"title":"Ein Furz wirft eine Go-Partie um (aus einem Skizzenalbum)","artist":"Kawanabe Kyōsai","date":"Mitte bis Ende 19. Jahrhundert","place":"Japan (Edo- bis Meiji-Zeit)","game":"Go","medium":"Eine Doppelseite eines Leporello-Albums mit 26 Doppelblättern; Tusche und Farben auf Papier","size":"Album (geschlossen) 28 × 18 cm","credit":"Geschenk von Anne und Anthony d’Offay zu Ehren von Evan Turner","p":["Eine Szene aus einem Skizzenalbum von Kawanabe Kyōsai (1831–1889), einem Maler vom Ende der Shogunatszeit bis in die Meiji-Ära, mit schnellen, freien Pinselstrichen auf die Seiten eines Faltalbums gesetzt. In der strengen Technik der Kanō-Schule ausgebildet, war Kyōsai auch für Dämonen, Karikaturen und Satiren beliebt.","Der Titel des Museums sagt alles: „Ein Furz wirft eine Go-Partie um“. Links beugt sich ein Mann mit schwarzer Kappe vor; rechts fliegt das Brett durch die Luft, die Steindosen lassen Steine regnen, und der Gegner fällt rücklings um. Eine ernste Partie, mit einem Knall ruiniert – Kyōsai hält mit flinkem Pinsel den alten japanischen Furzhumor fest, den schon mittelalterliche Bildrollen kennen."],"spots":[["Der Mann mit schwarzer Kappe","Vorgebeugt, das Hinterteil herausgestreckt – der Verursacher?"],["Das fliegende Brett","Das linierte Go-Brett fliegt schräg davon."],["Dosen und Steine","Zwei Steindosen kippen, die Steine prasseln herab."],["Der Fächer","Ein offener Fächer fliegt neben dem Brett davon."],["Der umgeworfene Gegner","Auf dem Rücken, mit weit aufgerissenen Augen."],["Die Pinselführung","Kräftige Tuschelinien, wie in einem Zug ohne Vorzeichnung."]]},"yokuts":{"title":"Spieltablett für Glücksspiele","artist":"Yokuts-Flechterin (Name unbekannt)","date":"um 1900","place":"USA (bei Dunlap, Kalifornien)","game":"Huuchuish (Walnussschalen-Würfel)","medium":"Pflanzenfasern (Spiralwulsttechnik)","size":"H. 5,1 cm, Dm. 61 cm","credit":"Erworben mit Mitteln von Mrs. Leonard S. Florsheim Jr.","p":["Viele indigene Völker Kaliforniens spielten Glücksspiele. Dieses Tablett diente dem Huuchuish, einem Würfelspiel nur für Frauen: Acht Würfel aus Walnussschalen wurden auf das Tablett geworfen, gezählt wurde mit Stäbchen.","Das in das Tablett eingeflochtene Rundmuster zeigt das Spiel selbst – die Würfel, die Zählstäbchen und die Spielerinnen (Museumstext). Ein Spielgerät, das das Bild seines eigenen Spiels trägt. Auf dem Foto liegen Walnusswürfel auf und neben dem Tablett."],"spots":[["Die Spielerinnen","Figuren umrunden den Rand – die Teilnehmerinnen."],["Zählstäbchen","Bündel kurzer senkrechter Striche: die Stäbchen zum Zählen."],["Runde Motive","Kleine runde Motive – vielleicht die Würfel?"],["Ein Walnusswürfel","Ein Würfel aus Walnussschale. Acht davon wurden geworfen."],["Das Dreiecksband","Ein Band dunkler Dreiecke läuft rundherum."],["Die Mitte","Die Wulst windet sich aus der Mitte, umgeben von einem gestrichelten Ring."]]},"hokkei":{"title":"Ushiwakamaru besiegt Benkei beim Sugoroku","artist":"Totoya Hokkei","date":"um 1825","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Surimono (Farbholzschnitt, Shikishiban)","size":"21,8 × 19,1 cm","credit":"Geschenk von Helen C. Gunsaulus","p":["Ein Surimono von Totoya Hokkei (1780–1850), einem Schüler Hokusais. Surimono waren privat in Auftrag gegebene Drucke – oft von Dichterkreisen, mit eigenen Versen – und aufwendiger gefertigt als kommerzielle Ukiyo-e, mit feinem Papier und Metallpigmenten.","Ushiwakamaru, der Kindername des Helden Minamoto no Yoshitsune, und der riesige Kriegermönch Benkei. Berühmt ist ihr Duell auf der Gojō-Brücke in Kyoto, doch hier wird der Kampf zur Sugoroku-Partie: Der Junge sitzt gelassen hinter dem Brett, Benkei mit der Hellebarde auf dem Rücken kratzt sich geschlagen am Kopf – wohl eine spielerische Umdeutung."],"spots":[["Das Sugoroku-Brett","Ein kastenförmiges Brett mit weißen und schwarzen Steinen."],["Benkei kratzt sich am Kopf","In voller Rüstung kratzt sich der Besiegte am Kopf."],["Ushiwakamaru","Der junge Held, hinter dem Brett sitzend."],["Die Hellebarde","Die Klinge von Benkeis großer Naginata."],["Das Gedicht","Verse oben rechts – wohl von dem Kreis, der den Druck bestellte."],["Die Signatur","Hokkeis Signatur in der Kartusche unten rechts."]]},"vorsterman":{"title":"Tricktrackspieler (Nachtszene)","artist":"Lucas Emil Vorsterman, nach Adam de Coster","date":"um 1630","place":"Flandern (Antwerpen)","game":"Backgammon","medium":"Kupferstich auf elfenbeinfarbenem Papier","size":"Bild 25,5 × 34,4 cm","credit":"Bernard F. Rogers Collection","p":["Adam de Coster war um 1630 in Antwerpen ein führender Maler kerzenbeleuchteter Nachtszenen, als Vorsterman in derselben Stadt Werke beliebter Zeitgenossen stach. Der Rubens-Schüler überwarf sich mit seinem Meister und ging nach England; danach schuf er kräftigere, stilisierte, caravaggeske Stiche wie diesen.","Um einen Tisch in einem dunklen Raum beugen sich Männer über ein Tricktrackbrett. Nach De Costers Lichtführung erhellen zwei Kerzenflammen die Gesichter am Tisch (Museumstext). Rechts blickt ein junger Lautenspieler zu uns heraus."],"spots":[["Das Brett","Ein wie ein Kasten aufgeklapptes Brett auf dem Tisch."],["Die Kerze","Eine Kerze im Leuchter; ihre Flamme erhellt die Gesichter."],["Der Mann mit Pfeife","Mit breitem Hut raucht er und schaut zu."],["Der Mann von hinten","Vorgebeugt, die Hände auf dem Tisch."],["Der Lautenspieler","Ein Jüngling mit Laute, der uns anlächelt."],["Die Namen","„A. De Coster pi.“ unten links, „Vorsterman“ unten rechts."]]},"zorn":{"title":"Schachspieler","artist":"Anders Zorn","date":"1891","place":"Schweden","game":"Schach","medium":"Radierung auf elfenbeinfarbenem Büttenpapier","size":"Bild 13,5 × 9,6 cm (Platte 13,9 × 10 cm)","credit":"Wallace L. DeWolf und Charles Deering Collections of Etchings by Anders Zorn","p":["Eine Radierung des schwedischen Künstlers Anders Zorn (1860–1920), der mit Porträts in Öl und Aquarell international berühmt wurde und auch ein großes radiertes Werk schuf. Die Platte ist nicht größer als eine Hand.","Schnelle, schräge, übereinandergelegte Linien genügen, um einen dunklen Raum und zwei Menschen aus dem Kupfer zu holen. Der Mann vorn, mit dem Rücken zu uns, beugt sich über das Brett; die Gestalt gegenüber blickt nach unten und überlegt den nächsten Zug. Die Figuren sind mit feinen Strichen gezeichnet. Wer Modell saß, ist nicht überliefert."],"spots":[["Brett und Figuren","Die helle Fläche unten ist das Brett; die kurzen senkrechten Striche sind Figuren."],["Der Mann vorn","Mit dem Rücken zu uns, über das Brett gebeugt."],["Der Gegner","Mit gesenktem Kopf, den Blick auf dem Brett."],["Der dunkle Hintergrund","Die Tiefe des Raums aus senkrechten Linien."],["Schräge Linien","Der Mantel besteht aus schnellen, übereinandergelegten Diagonalstrichen."],["Die Signatur","Unter der Platte mit Bleistift signiert: „Zorn“."]]},"harunobu-sugoroku":{"title":"Dem Spiel zusehen (Sugoroku)","artist":"Suzuki Harunobu","date":"um 1766","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Farbholzschnitt (Chūban, Surimono)","size":"28,5 × 21 cm","credit":"Clarence Buckingham Collection","p":["Suzuki Harunobu (1725?–1770) war die zentrale Gestalt, als um 1765 die vielfarbigen Nishiki-e entstanden, von vielen Platten gedruckt. Dies ist ein privat herausgegebenes Surimono, und die weichen, geschichteten Farben zeigen das Neue.","In einem Raum mit blühenden Pflaumen spielen zwei junge Frauen an einem kastenförmigen Sugoroku-Brett, eine dritte steht und schaut zu. Weiße und schwarze Steine füllen das Brett; die Linke zieht einen Stein, die Rechte greift zum Brett. Die Schiebetür dahinter ist mit Wasserfall und Kiefern bemalt."],"spots":[["Das Sugoroku-Brett","Ein kastenförmiges Ban-Sugoroku-Brett mit weißen und schwarzen Steinen."],["Die junge Frau links","Im Kimono mit Papierkranichen zieht sie einen Stein."],["Die junge Frau rechts","Vorgebeugt greift sie zum Brett."],["Die Zuschauerin","Stehend schaut sie zu, einen langstieligen Gegenstand in der Hand."],["Die Pflaume","Eine weiße Pflaume streckt ihre Zweige von oben herein."],["Die bemalte Tür","Eine Schiebetür mit Wasserfall und Kiefern."]]},"kota":{"title":"Maharao Kishor Singh II. von Kota verehrt Krishna als Brij Rajji","artist":"Unbekannt","date":"um 1825","place":"Indien (Rajasthan, Kota)","game":"Pachisi","medium":"Gummi-Tempera, Silber und Gold auf Papier","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Der Herrscher des kleinen Fürstenstaats Kota (reg. 1819–28), gekleidet als Priester der Pushti-Marg-Sekte, bringt eine Lampe mit fünf Flammen dar. Im kleinen Schrein auf dem Altar stehen Metallbilder Krishnas mit zwei Gefährtinnen – ein Kultbild, das nur in Kota verehrt wird.","Zahlreiche Glaslampen hängen von der Decke, und auf den Stufen zum Altar liegen Spielsachen und Spiele zur Unterhaltung Krishnas und seiner Gefährten: Messingelefanten, Silberkühe, Bälle und ein Pachisi-Brett (Museumstext). Das rote kreuzförmige Tuch ist dieses Brett – Pachisi als Spielzeug des Gottes dargebracht."],"spots":[["Das Pachisi-Brett","Das rote kreuzförmige Tuch auf den Stufen: ein Pachisi-Brett."],["Elefanten","Zwei Messingelefanten neben dem Brett."],["Bälle","Goldene Bälle auf der Stufe darüber."],["Krishna","Die Bilder Krishnas und zweier Gefährtinnen im Schrein."],["Der Herrscher und die Lampe","Als Priester gekleidet, bringt er eine Lampe mit fünf Flammen dar."],["Glaslampen","Eine Fülle von Glaslampen hängt von der Decke."]]},"coyote":{"title":"Das Kojotenspiel","artist":"Nachfolger von José Guadalupe Posada","date":"Undatiert","place":"Mexiko","game":"Kojote und Hennen (Familie von Fuchs und Gänse)","medium":"Hochdruck von Zinkplatte auf Papier","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Ein Spielbogen im Zinkhochdruck, wie Posada sie für die Volksdruckereien von Mexiko-Stadt schuf. Oben steht „JUEGO DEL COYOTE“ (Kojotenspiel); ringsum überfallen Kojoten den Hühnerstall, und ein Mann schwingt einen Stock, um einen zu vertreiben. Der Streifen unten lautet „Eigentum von Ildefonso T. Orellana“.","Die Regeln stehen in der „EXPLICACION“ unten: zwei Spieler, einer mit fünfzehn Hennen, der andere mit einem einzigen Kojoten. Die Hennen ziehen vorwärts oder seitwärts, nie zurück; der Kojote zieht in alle Richtungen und frisst eine Henne, indem er sie überspringt, wenn der Punkt dahinter frei ist. Die Hennen gewinnen, wenn sie den Kojoten einsperren. Es ist dasselbe Jagdspiel wie das europäische Fuchs und Gänse."],"spots":[["Der Platz des Kojoten","Der Kojotenkopf im mittleren Kreis: Hier beginnt der Kojote."],["Die Plätze der Hennen","Kreise mit Hennen: Hier werden ihre Steine aufgestellt."],["Die Regeln","Die „EXPLICACION“: Steine, Züge und Sieg."],["Der Titel","„JUEGO DEL COYOTE“ – das Kojotenspiel."],["Ein Kojote auf Hennenjagd","Unten links geht ein Kojote auf eine Henne los."],["Der Mann mit dem Stock","Oben rechts hebt ein Mann den Stock gegen einen Kojoten."]]},"mons":{"title":"Tricktrack um Mons (Bergen), 1709","artist":"Pieter Nolpe (Platte und Verleger)","date":"Platte 1623–53; Druck um 1709","place":"Niederlande (Amsterdam)","game":"Tricktrack (aus der Backgammon-Familie)","medium":"Radierung, Kupferstich und Vers in Buchdruck","size":"Blatt 35,8 × 18,6 cm (Platte 12,9 × 17,5 cm)","credit":"","p":["Vier Männer spielen am Tisch Tricktrack. Laut dem Museumsdatensatz bezeichnen die Buchstaben A–D den Herzog von Marlborough, den Kurfürsten von Bayern, den Herrn von Ouwerkerk und den Herzog von Villeroy. Das Blatt verspottet die Belagerung und Einnahme von Mons (niederländisch Bergen) durch die Alliierten gegen die Franzosen 1709 als Brettspiel um die Stadt. Im hinteren Raum (E) ist König Philipp V. von Spanien mit einer Frau.","Die Platte ist von Pieter Nolpe als Stecher und Verleger signiert, doch Nolpe starb Anfang der 1650er-Jahre – wahrscheinlich wurde eine alte Platte des 17. Jahrhunderts mit Buchstaben und einem neuen Vers erneut gedruckt. Der Vers beginnt damit, das Spiel der hohen Herren sei nichts als Tiktak und Verkeer (zwei Brettspiele dieser Familie), und verspottet dann jeden Spieler."],"spots":[["Das Brett","Das Tricktrackbrett auf dem Tisch: Es geht um eine Stadt."],["A, Marlborough","Stehend blickt er auf das Brett: der englische Feldherr der Alliierten."],["B, der Kurfürst von Bayern","Barhäuptig, tief im Stuhl."],["C, Ouwerkerk","Mit Federhut: der niederländische General."],["E, der hintere Raum","Hinten im Schlafzimmer Philipp V. mit einer Frau."],["Der Vers","Niederländischer Vers darunter, der die Spieler A bis E verspottet."]]},"stembus":{"title":"Die Wahlurne: ein politisches Gänsespiel","artist":"Johan Michaël Schmidt Crans (Grafiker)","date":"1867","place":"Niederlande","game":"Gänsespiel (Satire)","medium":"Lithografie","size":"66 × 50 cm","credit":"","p":["Ein satirisches Blatt in Form eines Gänsespiels, beigelegt der Wochenschrift De Nederlandsche Spectator, Nr. 9, 2. März 1867, zusammen mit einem losen Regelblatt (Museumsdatensatz). Auf den Feldern erscheinen Porträts der damaligen Minister.","Start ist der Binnenhof, das Parlament in Den Haag; Ziel ist in der Mitte Feld 64, „Insulinde“ – ein poetischer Name für Niederländisch-Indien –, wo ein gemaltes Porträt des Ministers Pieter Mijer an der Insel Java hängt. Mijer war vom Kolonialminister zum Generalgouverneur Indiens geworden, und die Ernennung löste einen politischen Sturm aus. Das zusätzliche Feld, eines mehr als die üblichen 63, ist wohl der Pointe geschuldet."],"spots":[["Der Start","Das Gebäude oben links: Es beginnt am Binnenhof in Den Haag."],["Mijers Porträt","Feld 63: ein gerahmtes Porträt Pieter Mijers, an Seilen von der Insel hängend."],["Insulinde 64","Die Insel und die Zahl 64 in der Mitte: das Ziel."],["Die Wahlurne","„DE STEMBUS“ (die Wahlurne) unten rechts: die Kiste des Titels."],["Die Minister","Aus den Feldern blicken die Gesichter der damaligen Minister."],["Der Hahn","Ein Hahn in einem Feld; worauf er anspielt, ist unbekannt."]]},"koorai":{"title":"Koreaner beim Brettspiel (aus Siebolds Nippon)","artist":"James Erxleben (Lithograf), nach einem Entwurf von „Toioske“","date":"1832–52","place":"Niederlande (Leiden) / Menschen aus Korea","game":"Brettspiel (wohl Go)","medium":"Tonlithografie, handkoloriert","size":"Blatt 38 × 55,5 cm","credit":"Geschenk von F. G. Waller","p":["Eine Tafel aus NIPPON, dem großen Werk, das der in Deutschland geborene Arzt Philipp Franz von Siebold in Leiden nach seinen Eindrücken in der niederländischen Faktorei in Nagasaki (1823–30) veröffentlichte. Oben rechts steht „TAB. I“, unten „KOORAI“ (Korea), dazu niederländisch und deutsch „eine Fischerfamilie“. Erxleben zeichnete sie auf den Stein; als Entwerfer nennt die Tafel „Toioske“.","Vier Männer sitzen auf dem Boden um ein Brett; links führt eine Frau ein kleines Kind an der Hand, rechts steht ein Mann mit langem Stock und Beutel. Vorn liegt ein breitkrempiger schwarzer Hut (Gat). Das Brett zeigt ein Gitter und runde Steine – wohl Go (koreanisch Baduk), auch wenn der Datensatz nur „ein Brettspiel“ nennt."],"spots":[["Das Brett","Gitter mit runden Steinen: wohl eine Partie Go."],["Der schwarze Hut","Ein breitkrempiger schwarzer Hut (Gat) am Boden."],["Mutter und Kind","Eine Frau mit einem Kind an der Hand sieht zu."],["Der stehende Mann","Stehend, mit langem Stock und Beutel."],["Der vorgebeugte Mann","In blauer Jacke späht er auf das Brett."],["Der Titel","„KOORAI“ (Korea), dazu „eine Fischerfamilie“ auf Niederländisch und Deutsch."]]}};
